changeSet.sql:
DO $$
DECLARE
  cible record;
  cibles text[][] := ARRAY[
    ['candidate_profile', 'raw_markdown'],
    ['conversation',      'summary'],
    ['conversation',      'metadata'],
    ['job_application',   'cover_letter'],
    ['job_application',   'notes']
  ];
  i int;
  t text;
  c text;
BEGIN
  FOR i IN 1 .. array_length(cibles, 1) LOOP
    t := cibles[i][1];
    c := cibles[i][2];

    -- La colonne peut ne pas exister sur une base partiellement migrée.
    CONTINUE WHEN NOT EXISTS (
      SELECT 1 FROM information_schema.columns
       WHERE table_name = t AND column_name = c
    );

    -- `~ '^[0-9]+$'` isole les valeurs encore au format OID ; le texte déjà migré est ignoré,
    -- ce qui rend le changeSet rejouable.
    EXECUTE format(
      'INSERT INTO lob_migration_oids (source_table, source_column, oid_value)
       SELECT %L, %L, %I::oid FROM %I
        WHERE %I ~ ''^[0-9]+$''
          AND %I::oid IN (SELECT oid FROM pg_largeobject_metadata)',
      t, c, c, t, c, c
    );

    EXECUTE format(
      'UPDATE %I SET %I = convert_from(lo_get(%I::oid), ''UTF8'')
        WHERE %I ~ ''^[0-9]+$''
          AND %I::oid IN (SELECT oid FROM pg_largeobject_metadata)',
      t, c, c, c, c
    );

    RAISE NOTICE 'Migré: %.%', t, c;
  END LOOP;
END $$;
